glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 v_color;
in vec2 uv0;
uniform sampler2D cc_spriteTexture;
uniform sampler2D noiseTexture;
layout(std140) uniform OceanWarpParams {
  vec4 colorDeep;
  vec4 colorMid;
  vec4 colorLite;
  float fluidScale;
  float fluidSpeed;
  float warpStrength;
  float warpScale;
  float warpSpeed;
  float threshold1;
  float threshold2;
};
#if USE_SPARKLES
  layout(std140) uniform SparkleParams {
    vec4 colorSparkle;
    float sparkleDensity;
    float sparkleSize;
    float sparkleSpeed;
    float sparkleIntensity;
    float sparkleMask;
    float sparkleDistort;
  };
#endif
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
vec4 frag () {
  float time = cc_time.x;
  vec2 uv = uv0;
  vec4 spriteColor = texture(cc_spriteTexture, uv);
  vec2 warpUV1 = uv * warpScale + vec2(time * warpSpeed, time * warpSpeed * 0.8);
  float s1 = sin(1.2), c1 = cos(1.2);
  vec2 rotUV1 = vec2(c1 * uv.x - s1 * uv.y, s1 * uv.x + c1 * uv.y);
  vec2 warpUV2 = rotUV1 * (warpScale * 1.618) + vec2(-time * warpSpeed * 0.9, time * warpSpeed * 1.1);
  float w1 = texture(noiseTexture, fract(warpUV1)).r;
  float w2 = texture(noiseTexture, fract(warpUV2)).r;
  vec2 warp = (vec2(w1, w2) * 2.0 - 1.0) * warpStrength;
  vec2 mainUV = uv * fluidScale + vec2(0.0, time * fluidSpeed) + warp;
  float n1 = texture(noiseTexture, fract(mainUV)).r;
  float s2 = sin(2.4), c2 = cos(2.4);
  vec2 rotUV2 = vec2(c2 * mainUV.x - s2 * mainUV.y, s2 * mainUV.x + c2 * mainUV.y);
  vec2 secUV = rotUV2 * 0.618 + vec2(0.314, 0.789) - warp * 0.5;
  float n2 = texture(noiseTexture, fract(secUV)).r;
  float s3 = sin(4.1), c3 = cos(4.1);
  vec2 rotUV3 = vec2(c3 * mainUV.x - s3 * mainUV.y, s3 * mainUV.x + c3 * mainUV.y);
  vec2 thirdUV = rotUV3 * 1.618 + vec2(0.577, 0.211) + warp * 0.3;
  float n3 = texture(noiseTexture, fract(thirdUV)).r;
  float n = (n1 * 0.5 + n2 * 0.3 + n3 * 0.2);
  vec3 waterColor = mix(colorDeep.rgb, colorMid.rgb, smoothstep(threshold1 - 0.25, threshold1 + 0.25, n));
  waterColor = mix(waterColor, colorLite.rgb, smoothstep(threshold2 - 0.25, threshold2 + 0.25, n));
  #if USE_SPARKLES
    vec2 gridUV = uv * sparkleDensity + warp * sparkleDistort * 10.0;
    vec2 id = floor(gridUV);
    vec2 localUV = fract(gridUV);
    vec2 rPos = vec2(hash(id), hash(id + 13.3)) * 0.6 + 0.2;
    float dist = length(localUV - rPos);
    float dotAlpha = 1.0 - smoothstep(0.0, sparkleSize, dist);
    float phase = hash(id * 77.7) * 6.2831;
    float twinkle = sin(time * sparkleSpeed + phase) * 0.5 + 0.5;
    twinkle = pow(twinkle, 4.0);
    float mask = smoothstep(sparkleMask - 0.15, sparkleMask + 0.15, n);
    float sparkle = dotAlpha * twinkle * mask * sparkleIntensity;
    waterColor += colorSparkle.rgb * sparkle;
  #endif
  vec3 finalColor = waterColor;
  float finalAlpha = spriteColor.a;
  return vec4(finalColor, finalAlpha) * v_color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

